import Foundation
import OSLog
import Domain

public actor PipelineCoordinator {

    public let cleanupTranscribe: CleanupTranscriptionUseCase
    public let diarizeMeeting: DiarizeMeetingUseCase
    public let summarizeMeeting: SummarizeMeetingUseCase
    private let logger = Logger(subsystem: "app.the-record", category: "PipelineCoordinator")

    private var pipelineTask: Task<Void, Never>?
    private var cleanupTask: Task<Void, Never>?
    private var pipelineGeneration = 0
    private var cleanupGeneration = 0

    // #73 G5 test-only accessors: confirm no orphaned Task references after completion.
    var hasActivePipelineTask: Bool { pipelineTask != nil }
    var hasActiveCleanupTask: Bool { cleanupTask != nil }

    // Consolidated state change callback for SSOT
    private var onStateChange: (@Sendable (CleanupState, PipelineState) -> Void)?

    private var onCleanupStateChanged: (@Sendable (CleanupState) -> Void)?
    private var onPipelineStateChanged: (@Sendable (PipelineState) -> Void)?
    private var onPipelineError: (@Sendable (String) -> Void)?

    public func setOnStateChange(_ handler: @escaping @Sendable (CleanupState, PipelineState) -> Void) {
        self.onStateChange = handler
    }

    public func setOnCleanupStateChanged(_ handler: @escaping @Sendable (CleanupState) -> Void) {
        self.onCleanupStateChanged = handler
    }

    public func setOnPipelineStateChanged(_ handler: @escaping @Sendable (PipelineState) -> Void) {
        self.onPipelineStateChanged = handler
    }

    public func setOnPipelineError(_ handler: @escaping @Sendable (String) -> Void) {
        self.onPipelineError = handler
    }

    private var activeRecordingId: RecordingID?
    private let primaryEngine: (any TranscriptionEngine)?
    // #132: released after the pipeline finishes on memory-constrained machines.
    private let diarizationEngine: (any DiarizationEngine)?
    private let summarizationEngine: (any SummarizationEngine)?
    private let physicalMemory: UInt64
    private var archivePassEnabled: Bool

    private var currentCleanupState: CleanupState = .idle
    private var currentPipelineState: PipelineState = .idle

    private static let memoryUnloadThreshold: UInt64 = 12_000_000_000

    public init(
        cleanupTranscribe: CleanupTranscriptionUseCase,
        diarizeMeeting: DiarizeMeetingUseCase,
        summarizeMeeting: SummarizeMeetingUseCase,
        primaryEngine: (any TranscriptionEngine)? = nil,
        physicalMemory: UInt64 = UInt64(ProcessInfo.processInfo.physicalMemory),
        archivePassEnabled: Bool = true,
        diarizationEngine: (any DiarizationEngine)? = nil,
        summarizationEngine: (any SummarizationEngine)? = nil,
    ) {
        self.cleanupTranscribe = cleanupTranscribe
        self.diarizeMeeting = diarizeMeeting
        self.summarizeMeeting = summarizeMeeting
        self.primaryEngine = primaryEngine
        self.physicalMemory = physicalMemory
        self.archivePassEnabled = archivePassEnabled
        self.diarizationEngine = diarizationEngine
        self.summarizationEngine = summarizationEngine
    }

    public func updateArchivePassEnabled(_ enabled: Bool) {
        archivePassEnabled = enabled
    }

    public func cancelAll() {
        pipelineTask?.cancel()
        cleanupTask?.cancel()
        pipelineGeneration &+= 1
        cleanupGeneration &+= 1
        activeRecordingId = nil
        // #73 G4: was a direct notifyStateChange(...) call, which skips
        // onCleanupStateChanged/onPipelineStateChanged (MenuBarViewModel's source)
        // and currentCleanupState/currentPipelineState. The generation bump above
        // also defeats the cancelled task's own clearStateIfActive, so these
        // setters are the only unconditional path to .idle.
        setCleanupState(.idle)
        setPipelineStateInternal(.idle)
    }

    public func recoverPendingSession(_ recordingId: RecordingID) async {
        guard archivePassEnabled else { return }
        // The coordinator has single-slot state (one activeRecordingId/pipelineTask
        // at a time) — recovery must never cancel or clobber a session that's
        // already actively piping. Skip this recovery attempt entirely and let
        // it retry on a later launch.
        guard activeRecordingId == nil else {
            logger
                .info(
                    // swiftlint:disable:next line_length
                    "Skipping recovery for \(recordingId, privacy: .private) — a live session is already active",
                )
            return
        }
        logger.info("Recovering pending session: \(recordingId, privacy: .private)")
        // Set activeRecordingId synchronously before the cleanup pass, mirroring
        // startCleanupPass/startPipeline — otherwise performCleanupTranscription's
        // isActiveRecording guard (#73 G4 generation-race protection) always fails
        // for recovery, silently discarding an already-persisted cleaned transcript.
        activeRecordingId = recordingId
        guard let result = await performCleanupTranscription(recordingId: recordingId) else {
            // swiftlint:disable:next line_length
            logger.error("Recovery cleanup transcription did not complete — session stays pending: \(recordingId, privacy: .private)")
            return
        }
        startPipeline(for: recordingId, liveTranscription: result)
    }

    /// #130: single post-stop entry point. The pass ordering (archive cleanup
    /// alongside the diarize→summarize pipeline) is Business knowledge —
    /// Presentation calls this and never sequences the passes itself.
    public func recordingCompleted(for recordingId: RecordingID, liveTranscription: TranscriptionResult) {
        startCleanupPass(for: recordingId)
        startPipeline(for: recordingId, liveTranscription: liveTranscription)
    }

    public func startPipeline(for recordingId: RecordingID, liveTranscription: TranscriptionResult) {
        pipelineTask?.cancel()
        activeRecordingId = recordingId
        pipelineGeneration &+= 1

        let generation = pipelineGeneration

        pipelineTask = Task {
            // #73 G5: clear our Task ref on every exit, unless a newer generation
            // already superseded us (then it isn't ours to clear).
            defer { if pipelineGeneration == generation { pipelineTask = nil } }

            await runPipelinePasses(
                recordingId: recordingId,
                liveTranscription: liveTranscription,
                generation: generation,
            )

            // #132: the pipeline is done with the ML engines — success or
            // failure — so on memory-constrained machines release model memory
            // (same policy as the ASR unload in startCleanupPass). Skipped when
            // a newer generation superseded us: that pipeline needs the engines.
            guard !Task.isCancelled, pipelineGeneration == generation else { return }
            await unloadPipelineEnginesIfConstrained()
        }
    }

    private func runPipelinePasses(
        recordingId: RecordingID,
        liveTranscription: TranscriptionResult,
        generation: Int,
    ) async {
        logger.info("Pipeline START for \(recordingId, privacy: .public)")
        setPipelineState(.diarizing, generation: generation)

        guard let diarizationResult = await runDiarizationPass(
            recordingId: recordingId,
            transcription: liveTranscription,
            generation: generation,
        ) else {
            return
        }

        guard !Task.isCancelled else { return }

        await runSummarizationPass(recordingId: recordingId, transcript: diarizationResult, generation: generation)
    }

    private func unloadPipelineEnginesIfConstrained() async {
        guard physicalMemory < PipelineCoordinator.memoryUnloadThreshold else { return }
        await diarizationEngine?.unloadModel()
        await summarizationEngine?.unloadModel()
    }

    public func startCleanupPass(for recordingId: RecordingID) {
        guard archivePassEnabled else { return }

        cleanupTask?.cancel()
        activeRecordingId = recordingId
        cleanupGeneration &+= 1
        let generation = cleanupGeneration

        let engine = primaryEngine
        let shouldUnload = physicalMemory < PipelineCoordinator.memoryUnloadThreshold

        cleanupTask = Task {
            // #73 G5: same generation-guarded clear as pipelineTask above.
            defer { if cleanupGeneration == generation { cleanupTask = nil } }

            setCleanupState(.running)
            if shouldUnload, let engine {
                await engine.unloadModel()
            }
            let result = await performCleanupTranscription(recordingId: recordingId)
            if let result {
                setCleanupState(.complete(result))
            } else {
                setCleanupState(.idle)
            }
        }
    }

    public func runCleanupPass(recordingId: RecordingID) async -> TranscriptionResult? {
        setCleanupState(.running)
        let result = await performCleanupTranscription(recordingId: recordingId)
        if let result {
            setCleanupState(.complete(result))
            setPipelineStateInternal(.diarizing)
        } else {
            setCleanupState(.idle)
        }
        return result
    }

    private func performCleanupTranscription(recordingId: RecordingID) async -> TranscriptionResult? {
        do {
            let result = try await cleanupTranscribe.transcribeCleanupPass(
                recordingId: recordingId,
                modelId: ModelIDs.cleanupTranscription,
            )
            guard !Task.isCancelled else { return nil }
            guard isActiveRecording(recordingId) else { return nil }
            return result
        } catch {
            if error is CancellationError { return nil }
            let msg = "Cleanup transcription failed: \(error.userFacingMessage)"
            logger.error("\(msg, privacy: .private)")
            onPipelineError?(msg)
            return nil
        }
    }

    private func runDiarizationPass(
        recordingId: RecordingID,
        transcription: TranscriptionResult,
        generation: Int,
    ) async -> DiarizedTranscript? {
        do {
            let result = try await diarizeMeeting.diarize(recordingId: recordingId, transcription: transcription)
            guard !Task.isCancelled else {
                clearStateIfActive(generation: generation)
                return nil
            }
            guard isActiveRecording(recordingId) else {
                clearStateIfActive(generation: generation)
                return nil
            }

            setPipelineState(.summarizing(result), generation: generation)
            return result
        } catch {
            // #73 G4: cancellation thrown from diarizeMeeting.diarize() itself, not
            // just noticed after it returns — same clearing as the guard above.
            if error is CancellationError {
                clearStateIfActive(generation: generation)
                return nil
            }
            let msg = "Diarization failed: \(error.userFacingMessage)"
            logger.error("\(msg, privacy: .private)")
            onPipelineError?(msg)
            setPipelineState(.failed(msg), generation: generation)
            return nil
        }
    }

    public func runSummarizationPass(recordingId: RecordingID, transcript: DiarizedTranscript) async {
        await runSummarizationPass(recordingId: recordingId, transcript: transcript, generation: pipelineGeneration)
    }

    private func runSummarizationPass(recordingId: RecordingID, transcript: DiarizedTranscript, generation: Int) async {
        do {
            let result = try await summarizeMeeting.summarize(recordingId: recordingId, transcript: transcript)
            guard !Task.isCancelled else {
                clearStateIfActive(generation: generation)
                return
            }
            guard isActiveRecording(recordingId) else {
                clearStateIfActive(generation: generation)
                return
            }
            setPipelineState(.complete(transcript, result), generation: generation)
        } catch {
            // #73 G4: cancellation thrown from summarize() itself — #144/T073-A only
            // patched the guard path above; this catch path left state stuck.
            if error is CancellationError {
                clearStateIfActive(generation: generation)
                return
            }
            let msg = "Summarization failed: \(error.userFacingMessage)"
            logger.error("\(msg, privacy: .private)")
            onPipelineError?(msg)
            setPipelineState(.failed(msg), generation: generation)
        }
    }

    private func isActiveRecording(_ id: RecordingID) -> Bool {
        activeRecordingId == id
    }

    private func setPipelineState(_ state: PipelineState, generation: Int) {
        if pipelineGeneration == generation {
            setPipelineStateInternal(state)
        }
    }

    private func clearStateIfActive(generation: Int) {
        if pipelineGeneration == generation {
            setPipelineStateInternal(.idle)
        }
    }

    private func setCleanupState(_ state: CleanupState) {
        currentCleanupState = state
        onCleanupStateChanged?(state)
        notifyStateChange(cleanup: currentCleanupState, pipeline: currentPipelineState)
    }

    private func setPipelineStateInternal(_ state: PipelineState) {
        currentPipelineState = state
        onPipelineStateChanged?(state)
        notifyStateChange(cleanup: currentCleanupState, pipeline: currentPipelineState)
    }

    private func notifyStateChange(cleanup: CleanupState, pipeline: PipelineState) {
        onStateChange?(cleanup, pipeline)
    }
}
